        if self.mac_address is not None and len(self.mac_address) > 0:
            bytes_len = len(self.mac_address)
            bytes_len_size = ((bytes_len | 1).bit_length() + 6) // 7
            res += 1 + bytes_len_size + bytes_len
        if self.ips is not None:
            for v in self.ips:
                res += 1
